local K = "71764C6F62426653573833476E6D347A6B766A52644D5432"
local P = ""

local function d(h, k)
    local kb = {}
    for i = 1, #k, 2 do
        kb[#kb + 1] = tonumber(string.sub(k, i, i + 1), 16)
    end
    local t = {}
    local j = 0
    for i = 1, #h, 2 do
        local v = tonumber(string.sub(h, i, i + 1), 16)
        j = j + 1
        if j > #kb then j = 1 end
        local bb = (v + 256 - kb[j]) % 256
        t[#t + 1] = string.char(bb)
    end
    return table.concat(t)
end

local ok, err = pcall(function()
    local src = d(P, K)
    local fn, lerr = loadstring(src)
    if not fn then
        error("cozme hatasi: " .. tostring(lerr), 0)
    end
    fn()
end)
if not ok then
    print("[MenschV3.5] ACILAMADI -> " .. tostring(err))
end